	onShow() {
		this.loadMine();
	},
	methods: {
		async loadMine() {
			const res = await h5MineInfo();
			if (res.code !== 0) {
				uni.showToast({ title: res.message || '获取失败', icon: 'none' });
				return;
			}
			this.mine = (res.data && res.data.merchant) || {};
			this.account = (res.data && res.data.account) || this.account;
		},
		onAccountAreaClick() {
			if (this.mine.agreementImg) return;
			this.$refs.agreementPopup.open();
		},
		async onSigned(payload) {
			const signatureImage = payload && (payload.dataUrl || payload.tempFilePath);
			if (!signatureImage) {
				uni.showToast({ title: '签名图生成失败', icon: 'none' });
				return;
			}
			uni.showLoading({ title: '提交签署...', mask: true });
			try {
				const res = await h5SignAgreement({
					signatureImage,
					agreementVersion: '2026-03-27-v1'
				});
				if (res.code !== 0) {
					uni.showToast({ title: res.message || '签署失败', icon: 'none' });
					return;
				}
				uni.showToast({ title: '签署成功', icon: 'success' });
				this.$refs.agreementPopup.close();
				this.loadMine();
			} finally {
				uni.hideLoading();
			}
		},
		confirmUnbind() {
			uni.showModal({
				title: '确认解除绑定',
				content: '解除后将清空商户与机具关联及账户数据，是否继续？',
				confirmText: '确认解绑',
				success: async (r) => {
					if (!r.confirm) return;
					uni.showLoading({ title: '解绑中...', mask: true });
					try {
						const res = await h5Unbind('用户在我的页面主动解绑');
						if (res.code !== 0) {
							uni.showToast({ title: res.message || '解绑失败', icon: 'none' });
							return;
						}
						uni.showToast({ title: '解绑成功', icon: 'success' });
						clearSession();
						setTimeout(() => uni.reLaunch({ url: '/pages/h5/auth/index' }), 400);
					} finally {
						uni.hideLoading();
					}
				}
			});
		},
		goHome() {
			uni.redirectTo({ url: '/pages/h5/home/index' });
		},
		goIncome() {
			uni.redirectTo({ url: '/pages/h5/income/index' });
		}
	}
